  "competitors": [
    {
      "name": "ServiceTitan",
      "slug": "servicetitan",
      "category": "direct",
      "description": "Full-featured field service management platform primarily targeting mid-market and larger service contractors. Offers scheduling, dispatch, CRM, invoicing, and marketing automation.",
      "key_differentiators": [
        "Comprehensive enterprise-grade feature set",
        "Strong brand recognition and large customer base",
        "Deep integrations with accounting and marketing tools",
        "Significant VC/PE funding ($1.1B+ raised, $9.5B valuation)"
      ],
      "why_included": "The market-leading FSM platform; investors will immediately ask about ServiceTitan. Though it skews toward larger contractors, it competes for the upper end of the SMB market that Cadence targets."
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "SMB-focused field service management software for home service businesses. Offers scheduling, quoting, invoicing, and client management. Targets the same SMB segment as Cadence.",
      "key_differentiators": [
        "Purpose-built for SMBs with strong UX reputation",
        "Broad feature set including quoting, invoicing, and client hub",
        "Strong brand in home services market",
        "Well-funded (~$100M+ raised)"
      ],
      "why_included": "Most direct head-to-head competitor — same SMB service business target, overlapping scheduling and dispatch core, with strong market presence."
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "Mobile-first field service management platform for home service contractors. Focuses on ease of use for small service businesses, with scheduling, dispatch, payments, and customer communication.",
      "key_differentiators": [
        "Mobile-first design optimized for field technicians",
        "Consumer-style UX simplicity",
        "Built-in payment processing and customer messaging",
        "Large community and marketplace of service pros"
      ],
      "why_included": "Direct competitor in the SMB field service space with a particularly strong SMB brand, overlapping exactly on scheduling and dispatch for small service businesses."
    }
  ],
  "candidate_axes": [
    {
      "x_axis": "Time to Value",
      "y_axis": "SMB Workflow Fit",
      "rationale": "Time to value (how quickly a new customer gets up and running, lower is better) directly reflects the implementation burden Cadence aims to eliminate versus ServiceTitan's weeks-long onboarding. SMB workflow fit captures how well the product's opinionated defaults match the SMB owner-operator model vs. an enterprise configuration-heavy approach. Both axes are buyer decision criteria and competitors spread meaningfully across both."
    },
    {
      "x_axis": "Total Cost of Ownership",
      "y_axis": "Scheduling Automation Depth",
      "rationale": "Total cost of ownership (monthly all-in cost for a 5-10 tech team, lower is better) reveals the pricing accessibility divide between enterprise and SMB-native tools. Scheduling automation depth (how intelligently the system optimizes dispatch — basic manual vs. AI-assisted routing) reveals where incumbents are investing vs. where a seed-stage startup may still be building. Both matter to SMB buyers making a purchase decision."
    },
    {
      "x_axis": "Mobile-first Field Experience",
      "y_axis": "Back-office Integration Depth",
      "rationale": "Mobile-first experience scores how well the field technician app works vs. the back-office web UI. Back-office integration depth captures accounting, CRM, and marketing integrations. This pair reveals the product strategy divide: mobile-first SMB tools vs. platform-play integrators."
    }
  ],
  "metadata": {"run_id": "20260824T170851Z"}
}
